t.script:
(function () {
  "use strict";
  function $(s,r){return (r||document).querySelector(s);}
  function $val(id,d){var el=$("#"+id);return el?el.value:d;}
  async function loadImage(src){return new Promise((res,rej)=>{var i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=src;});}
  function readAsDataURL(f){return new Promise((res,rej)=>{var r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f);});}

  function applyTransform(){
    var logo=$("#spw_logo_preview"), base=$("#spw_product_img"); if(!logo||!base) return;
    var size=+($val("spw_size","100")||100), px=+($val("spw_pos_x","0")||0), py=+($val("spw_pos_y","10")||10), rot=+($val("spw_rotation","0")||0);
    var bw=base.clientWidth, bh=base.clientHeight;
    logo.style.position="absolute";
    logo.style.left=(bw*(0.5+px/100))+"px";
    logo.style.top =(bh*(0.6+py/100))+"px";
    logo.style.transform="translate(-50%,-50%) rotate("+rot+"deg)";
    logo.style.width=size+"px";
    logo.classList.remove("d-none");
  }

  async function renderPNGDataURL(){
    var baseEl=$("#spw-base-img");
    var baseSrc=(baseEl&&baseEl.getAttribute("src")) || $val("spw_img_src","") || ($("#spw_product_img")||{}).getAttribute("src");
    if(!baseSrc) throw new Error("Sin base");
    var baseIm=await loadImage(baseSrc);
    var c=document.createElement("canvas"), ctx=c.getContext("2d");
    c.width=baseIm.naturalWidth||baseIm.width; c.height=baseIm.naturalHeight||baseIm.height;
    ctx.drawImage(baseIm,0,0,c.width,c.height);
    var logoEl=$("#spw_logo_preview");
    if(logoEl && logoEl.src){
      var base=$("#spw_product_img"), bw=base.clientWidth, bh=base.clientHeight, br=base.getBoundingClientRect(), lr=logoEl.getBoundingClientRect();
      var cx=((lr.left+lr.width/2)-br.left)/bw*c.width, cy=((lr.top+lr.height/2)-br.top)/bh*c.height, w=lr.width/bw*c.width;
      var logoIm=await loadImage(logoEl.src), ratio=(logoIm.naturalHeight||logoIm.height)/(logoIm.naturalWidth||logoIm.width);
      var h=w*ratio, rot=(+($val("spw_rotation","0")||0)*Math.PI)/180;
      ctx.save(); ctx.translate(cx,cy); ctx.rotate(rot); ctx.drawImage(logoIm,-w/2,-h/2,w,h); ctx.restore();
    }
    return c.toDataURL("image/png");
  }

  async function postJSON(url,payload){
    try{
      var r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json","X-Requested-With":"XMLHttpRequest"},credentials:"same-origin",body:JSON.stringify(payload)});
      var t=await r.text(); var d=null; try{d=JSON.parse(t);}catch(_){}
      return {ok:!!(d&&(d.ok===true||d.ok==="true")),data:d,status:r.status,raw:t};
    }catch(e){return {ok:false,data:null,status:0,raw:String(e)};}
  }
  async function postForm(url,payload){
    try{
      var fd=new FormData(); Object.keys(payload||{}).forEach(k=>fd.append(k,payload[k]));
      var r=await fetch(url,{method:"POST",body:fd,credentials:"same-origin"});
      var t=await r.text(); var d=null; try{d=JSON.parse(t);}catch(_){}
      return {ok:r.ok && (!!d ? (d.ok===true||d.ok==="true") : true), data:d||{}, status:r.status, raw:t};
    }catch(e){return {ok:false,data:null,status:0,raw:String(e)};}
  }

  async function addToCart(){
    var variantId=($val("spw_variant_id","")||"").trim(); if(!variantId){ alert("Falta la variante del producto."); return; }
    var qty=+( $val("spw_qty","1")||1 ), tech=(document.querySelector("input[name='spw_tech']:checked")||{}).value||"", svgColor=(document.querySelector("input[name='spw_svg_color']:checked")||{}).value||"", notes=($val("spw_notes","")||"").trim();

    var du=await renderPNGDataURL();
    try{ sessionStorage.setItem('spw_last_product_id', String(variantId)); sessionStorage.setItem('spw_last_png', du||''); sessionStorage.setItem('spw_last_color', svgColor||''); }catch(_){}

    var r1=await postJSON("/spw/add_to_cart_meta",{variant_id:parseInt(variantId,10),qty:qty,tech:tech,svg_color:svgColor,notes:notes});
    if(!r1.ok){ r1=await postForm("/spw/add_to_cart_meta_http",{variant_id:variantId,qty:qty,tech:tech,svg_color:svgColor,notes:notes}); }
    if(!r1.ok){ alert((r1.data&&r1.data.message)?r1.data.message:"No se pudo añadir al carrito."); return; }

    try{ if(r1.data && r1.data.line_id){ sessionStorage.setItem('spw_last_line_id', String(r1.data.line_id)); } }catch(_){}
    try{
      var b64=(du.split('base64,')[1]||""); if(b64){
        var r2=await postJSON("/spw/attach_png",{line_id:r1.data.line_id,png_b64:b64});
        if(!r2.ok){ await postForm("/spw/attach_png_http",{line_id:r1.data.line_id,png_b64:b64}); }
      }
    }catch(_){}

    var baseUrl=(r1.data&&r1.data.cart_url)||"/shop/cart";
    var goto=(r1.data&&r1.data.line_id)?(baseUrl+(baseUrl.indexOf('?')===-1?'?':'&')+'spw_line_id='+encodeURIComponent(r1.data.line_id)):baseUrl;
    window.location.href=goto;
  }

  async function downloadPNGiOSSafe(){
    try{
      var dataUrl=await renderPNGDataURL();
      var a=document.createElement("a"); a.href=dataUrl; a.download="personalizacion.png";
      if(typeof a.download==="undefined"){ window.location.href=dataUrl; } else { document.body.appendChild(a); a.click(); a.remove(); }
    }catch(_){ alert("No se pudo generar el PNG."); }
  }

  function init(){
    var inFile=document.getElementById("spw_logo_input"), logo=document.getElementById("spw_logo_preview");
    if(inFile){ inFile.addEventListener("change", async (ev)=>{ var f=ev.target.files&&ev.target.files[0]; if(!f) return; logo.src=await readAsDataURL(f); applyTransform(); }); }
    ["spw_size","spw_pos_x","spw_pos_y","spw_rotation"].forEach(id=>{ var el=document.getElementById(id); if(el) el.addEventListener("input", applyTransform); });
    window.spwReset=function(){ $("#spw_size").value=100; $("#spw_pos_x").value=0; $("#spw_pos_y").value=10; $("#spw_rotation").value=0; applyTransform(); };
    var dl=$("#spw_download_png"); if(dl){ dl.addEventListener("click", downloadPNGiOSSafe); }
    var add=$("#spw_add_to_cart"); if(add){ add.addEventListener("click", addToCart); }
    applyTransform();
  }
  if(document.readyState==="loading"){ document.addEventListener("DOMContentLoaded", init); } else { init(); }
})();

xpath.script:
(function(){
  "use strict";

  function q(s,r){return (r||document).querySelector(s);}
  function qa(s,r){return Array.from((r||document).querySelectorAll(s));}
  function getParam(n){ try{ return new URL(location.href).searchParams.get(n); }catch(_){ return null; } }

  // Dónde insertar: justo DESPUÉS del bloque que contiene "Técnica"/"Color"
  function findDescNode(line){
    // 1) Preferimos un nodo con el texto de técnica/color
    var candidates = qa("p, div, li, span", line);
    var picked = candidates.find(function(el){
      var t=(el.textContent||"").toLowerCase();
      return /t[eé]cnica/.test(t) || /color\s*svg/.test(t) || /color\s*#/.test(t);
    });
    if (picked) return picked;
    // 2) Fallbacks por temas habituales
    return q(".o_wsale_cart_description", line)
        || q(".media-body", line)
        || q(".flex-grow-1", line)
        || q(".card-body", line)
        || q(".col", line)
        || line;
  }

  function extractLineId(line){
    if(!line) return null;
    try{
      return line.getAttribute("data-line-id")
          || (q('input[name=\"line_id\"]', line)||{}).value
          || (function(){ // busca en enlaces con line_id
               var a=line.closest('a[href*=\"line_id=\"]') || q('a[href*=\"line_id=\"]', line);
               if(!a) return null;
               var u=new URL(a.getAttribute('href'), location.origin);
               return u.searchParams.get('line_id');
             })()
          || null;
    }catch(_){ return null; }
  }

  function parseHexFromText(text){
    var m=(text||"").match(/#([0-9a-fA-F]{6})\b/);
    return m ? ('#'+m[1]) : null;
  }

  // Inserta o actualiza un único preview para esa línea (sin duplicar)
  function upsertPreview(line, src, lineId, hex){
    // id único por línea
    var holderId = "spw-prev-" + (lineId || "x");
    var holder = document.getElementById(holderId);

    if (!holder) {
      var afterNode = findDescNode(line);
      holder = document.createElement("div");
      holder.id = holderId;
      holder.className = "spw-preview";
      holder.style.display = "inline-flex";
      holder.style.alignItems = "center";
      holder.style.gap = "8px";
      holder.style.marginTop = "6px";
      holder.style.maxWidth = "100%";

      // imagen
      var img = new Image();
      img.alt = "Personalización";
      img.loading = "lazy";
      img.style.maxWidth = "120px";
      img.style.height = "auto";
      img.style.border = "1px solid #e5e7eb";
      img.style.borderRadius = "6px";
      holder.appendChild(img);

      // swatch
      var sw = document.createElement("span");
      sw.className = "spw-color-dot";
      sw.title = "";
      sw.style.display = "inline-block";
      sw.style.width = "14px";
      sw.style.height = "14px";
      sw.style.borderRadius = "999px";
      sw.style.border = "1px solid #e5e7eb";
      holder.appendChild(sw);

      if (afterNode && afterNode.parentElement) {
        afterNode.insertAdjacentElement("afterend", holder);
      } else {
        line.appendChild(holder);
      }
    }

    // set src/color (evita repintados innecesarios)
    var imgEl = holder.querySelector("img");
    if (imgEl && imgEl.src !== src) imgEl.src = src;

    var dot = holder.querySelector(".spw-color-dot");
    var color = hex || parseHexFromText((findDescNode(line).textContent||"") + " " + (line.textContent||""));
    if (dot) {
      if (color && /^#[0-9A-F]{6}$/i.test(color)) {
        dot.style.background = color;
        dot.title = color;
        dot.style.display = "inline-block";
      } else {
        dot.style.display = "none";
      }
    }
  }

  function findLines(){
    // cubre temas comunes de Odoo
    var sel = ".o_wsale_cart_item, tr.js_cart_line, .card.js_cart_item, .o_cart_line, .js_cart_lines > .row, .table.cart_table tbody tr";
    return qa(sel, document).filter(Boolean);
  }

  function inject(){
    if (!/\/shop\/cart/.test(location.pathname)) return;

    var wanted = getParam("spw_line_id");
    var lastId = null, lastPng = null, lastColor = null;
    try {
      lastId    = sessionStorage.getItem("spw_last_line_id");
      lastPng   = sessionStorage.getItem("spw_last_png");
      lastColor = sessionStorage.getItem("spw_last_color");
    } catch(_) {}

    var lines = findLines();
    if (!lines.length) return;

    // Limpieza de previews que hayan quedado fuera del DOM
    qa(".spw-preview").forEach(function(node){
      if (!document.body.contains(node)) node.remove();
    });

    lines.forEach(function(line){
      var id = extractLineId(line) || wanted; // al menos el recién creado
      if (!id) return;

      // Si acabamos de crear esta línea, pinta instantáneo con el dataURL de sesión
      if (wanted && lastId && id === lastId && lastPng) {
        upsertPreview(line, lastPng, id, lastColor);
        return;
      }
      // Fallback estable desde el servidor
      var url = "/spw/line_preview/" + encodeURIComponent(id) + ".png?_=" + Date.now();
      upsertPreview(line, url, id, null);
    });

    // limpiezas de sesión para no contaminar siguientes carritos
    if (wanted && lastId && wanted === lastId) {
      try {
        sessionStorage.removeItem("spw_last_line_id");
        sessionStorage.removeItem("spw_last_png");
        sessionStorage.removeItem("spw_last_color");
      } catch(_) {}
    }
  }

  function boot(){
    inject();
    var root = q(".js_cart_lines") || q(".o_wsale_cart") || document.body;
    if (window.MutationObserver && root){
      var rafId=null;
      var mo = new MutationObserver(function(){ if(rafId) cancelAnimationFrame(rafId); rafId=requestAnimationFrame(inject); });
      mo.observe(root, {childList:true, subtree:true});
    }
    setTimeout(inject, 250);
    setTimeout(inject, 900);
    window.addEventListener("pageshow", inject);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();
